head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[textarea > P > nextTabByEnter]<br/>Textarea 컴포넌트에서 Enter 키 입력 시 nextTabID 속성에 설정된 컴포넌트로 포커스를 이동할지 설정합니다.",
    "validation" : [
        "true 설정 시 Enter 키 입력 시 nextTabID 속성에 설정된 컴포넌트로 포커스를 이동합니다.",
        "false (default) 설정 시 Enter 키 입력 시 포커스를 이동하지 않습니다.",
        "nextTabID 속성이 설정되어 있어야 동작합니다.",
        "Shift+Enter 키 입력 시 nextTabByEnter 속성은 false 로 동작합니다.",        
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



scwin.wf_sample_onwframeload = function () {    
    wf_sample.getObj("wf_body_left").getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof startcomp !== 'undefined') {
        startcomp.remove();
    }

    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (startcomp)
    let properties = {
        tabIndex : 1,
    };

    // 조건 설정 (target) — textarea 는 enterBlur 미지원으로 nextTabByEnter 만 전달
    let properties2 = {
        tabIndex : 2,
        nextTabID: "startcomp",
        nextTabByEnter: wf_sample.getObj("con_nextTabByEnter").getText(),
    };

    let cList = $c.gcm.createCList(properties);
    let cList2 = $c.gcm.createCList(properties2);

    $c.gcm.createBasicInput(cList, 'ev:onfocus="scwin.startcomp_onfocus"', 'startcomp');
    $c.gcm.createBasicTextArea(cList2, 'ev:onfocus="scwin.target1_onfocus" ev:onblur="scwin.target1_onblur"', 'target1');

    startcomp.setValue("start");
    target1.setValue("target1");

    // textarea 는 enterBlur 속성 미지원 → 공통 wframe 의 con_enterBlur 콤보 비활성화
    wf_sample.getObj("con_enterBlur").setDisabled(true);
}
